const expected = ['Comunidad', 'Primer apellido', 'Primer nombre'];
const rows = $input.all().map((item) => item.json).filter((row) => Object.keys(row).length > 0);
for (const row of rows) {
  if (JSON.stringify(Object.keys(row).sort()) !== JSON.stringify(expected)) throw new Error('TDAP_NEW_ROWS_INVALID');
  for (const value of Object.values(row)) {
    if (typeof value !== 'string' || value.length > 200) throw new Error('TDAP_NEW_ROWS_INVALID');
  }
}
return [{ json: { new_rows: rows } }];

const expected = ['Comunidad', 'Primer apellido', 'Primer nombre'];
const rows = $input.all().map((item) => item.json).filter((row) => Object.keys(row).length > 0);
for (const row of rows) {
  if (JSON.stringify(Object.keys(row).sort()) !== JSON.stringify(expected)) throw new Error('TDAP_PENDING_ROWS_INVALID');
  for (const value of Object.values(row)) {
    if (typeof value !== 'string' || value.length > 200) throw new Error('TDAP_PENDING_ROWS_INVALID');
  }
}
return [{ json: { pending_rows: rows } }];

const data = $input.first().json;
const fail = () => { throw new Error('TDAP_EMAIL_DATA_INVALID'); };
if (!Array.isArray(data.new_rows) || !Array.isArray(data.pending_rows)) fail();
if (data.new_rows.length !== data.new_total || data.pending_rows.length !== data.pending_total) fail();
if (typeof data.attachment_base64 !== 'string' || data.attachment_base64.length < 100 || !data.attachment_base64.startsWith('UEsDB')) fail();
if (typeof data.filename !== 'string' || !/^Seguimiento_Tdap_El_Chal_\d{2}-\d{2}-\d{4}\.xlsx$/.test(data.filename)) fail();
const padding = (data.attachment_base64.match(/=*$/) || [''])[0].length;
const attachmentSize = Math.floor(data.attachment_base64.length * 3 / 4) - padding;
if (attachmentSize < 1000) fail();
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const renderRows = (rows) => rows.length === 0
  ? '<p style="color:#6b7280">Sin registros para esta sección.</p>'
  : '<table style="border-collapse:collapse;width:100%;max-width:760px"><thead><tr style="background:#155e8e;color:#fff"><th style="padding:8px;text-align:left">Primer nombre</th><th style="padding:8px;text-align:left">Primer apellido</th><th style="padding:8px;text-align:left">Comunidad</th></tr></thead><tbody>' + rows.map((row) => '<tr><td style="padding:8px;border-bottom:1px solid #d1d5db">' + escapeHtml(row['Primer nombre']) + '</td><td style="padding:8px;border-bottom:1px solid #d1d5db">' + escapeHtml(row['Primer apellido']) + '</td><td style="padding:8px;border-bottom:1px solid #d1d5db">' + escapeHtml(row.Comunidad) + '</td></tr>').join('') + '</tbody></table>';
const html = '<div style="font-family:Arial,sans-serif;color:#1f2937;line-height:1.6"><h2 style="color:#155e8e;margin-bottom:8px">Seguimiento oportuno Tdap - El Chal</h2><p>Buen día.</p><p>Se comparte el seguimiento semanal de embarazadas candidatas a Tdap del municipio de El Chal.</p><p><strong>Semana evaluada:</strong> ' + data.range_from.split('-').reverse().join('-') + ' al ' + data.range_to.split('-').reverse().join('-') + '</p><p><strong>Nuevas pacientes que alcanzaron 20 semanas la semana pasada:</strong> ' + data.new_total + '<br><strong>Pacientes pendientes de Tdap actualmente:</strong> ' + data.pending_total + '</p><h3 style="color:#155e8e">Nuevas oportunidades Tdap</h3>' + renderRows(data.new_rows) + '<h3 style="color:#155e8e">Pendientes de Tdap</h3>' + renderRows(data.pending_rows) + '<p>Se adjunta el archivo Excel con las mismas dos listas.</p><p style="font-size:12px;color:#6b7280">Uso exclusivo para personal autorizado. Este es un mensaje automático; no responda a este correo.</p></div>';
return [{ json: { dispatch_token: data.dispatch_token, filename: data.filename, subject: data.subject, html, attachment_base64: data.attachment_base64, attachment_size: attachmentSize } }];

const raw = $json;
const fail = () => { throw new Error('CONTRACT_INVALID'); };
const rootKeys = ['as_of','dispatch','generated_at','has_information','new_opportunities','pending','range','report_type','schema_version','timezone','xlsx'];
if (!raw || typeof raw !== 'object' || Array.isArray(raw) || JSON.stringify(Object.keys(raw).sort()) !== JSON.stringify(rootKeys.slice().sort())) fail();
const datePattern = /^\d{4}-\d{2}-\d{2}$/;
const realDate = (value) => { if (typeof value !== 'string' || !datePattern.test(value)) return false; const parsed = new Date(value + 'T00:00:00Z'); return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value; };
const formatDate = (value) => value.split('-').reverse().join('-');
if (raw.schema_version !== 1 || raw.timezone !== 'America/Guatemala' || raw.report_type !== 'seguimiento_tdap_el_chal') fail();
if (typeof raw.generated_at !== 'string' || Number.isNaN(Date.parse(raw.generated_at))) fail();
if (!raw.range || Object.keys(raw.range).sort().join(',') !== 'from,to' || !realDate(raw.range.from) || !realDate(raw.range.to) || !realDate(raw.as_of)) fail();
const from = Date.parse(raw.range.from + 'T00:00:00Z');
const to = Date.parse(raw.range.to + 'T00:00:00Z');
if (to - from !== 6 * 86400000 || new Date(from).getUTCDay() !== 1 || new Date(to).getUTCDay() !== 0 || Date.parse(raw.as_of + 'T00:00:00Z') !== to + 86400000) fail();
for (const group of [raw.new_opportunities, raw.pending]) { if (!group || Object.keys(group).join(',') !== 'total' || !Number.isSafeInteger(group.total) || group.total < 0 || group.total > 100000) fail(); }
if (typeof raw.has_information !== 'boolean' || !raw.xlsx || JSON.stringify(Object.keys(raw.xlsx).sort()) !== JSON.stringify(['available','download_path','filename'])) fail();
if (typeof raw.xlsx.available !== 'boolean' || raw.xlsx.download_path !== '/api/automatizaciones/v1/tdap/xlsx') fail();
if (!raw.dispatch || typeof raw.dispatch !== 'object' || Array.isArray(raw.dispatch)) fail();
const status = raw.dispatch.status;
if (!['ready','no_results','already_processed'].includes(status)) fail();
const totalRows = raw.new_opportunities.total + raw.pending.total;
const expectedFilename = 'Seguimiento_Tdap_El_Chal_' + formatDate(raw.as_of) + '.xlsx';
if (status === 'ready') {
  if (Object.keys(raw.dispatch).sort().join(',') !== 'status,token' || typeof raw.dispatch.token !== 'string' || !/^[A-Za-z0-9_-]{43}$/.test(raw.dispatch.token)) fail();
  if (!raw.has_information || totalRows < 1 || !raw.xlsx.available || raw.xlsx.filename !== expectedFilename) fail();
} else {
  if (Object.keys(raw.dispatch).join(',') !== 'status' || raw.has_information || totalRows !== 0 || raw.xlsx.available || raw.xlsx.filename !== null) fail();
}
const fromLabel = formatDate(raw.range.from);
const toLabel = formatDate(raw.range.to);
const subject = 'CAP Prenatal | Seguimiento oportuno Tdap - El Chal';
const html = '<div style="font-family:Arial,sans-serif;color:#1f2937;line-height:1.6"><h2 style="color:#155e8e;margin-bottom:8px">Seguimiento oportuno Tdap - El Chal</h2><p>Buen día.</p><p>Se comparte el seguimiento semanal de embarazadas candidatas a Tdap del municipio de El Chal.</p><p><strong>Semana evaluada:</strong> ' + fromLabel + ' al ' + toLabel + '</p><p><strong>Resumen:</strong><br>- Nuevas pacientes que alcanzaron 20 semanas la semana pasada: ' + raw.new_opportunities.total + '<br>- Pacientes pendientes de Tdap actualmente: ' + raw.pending.total + '</p><p>Se adjunta un archivo Excel con dos hojas:<br>1. Nuevas oportunidades Tdap<br>2. Pendientes de Tdap</p><p>Este reporte contiene únicamente:<br>- Primer nombre<br>- Primer apellido<br>- Comunidad</p><p style="font-size:12px;color:#6b7280">Uso exclusivo para personal autorizado.</p></div>';
return [{ json: { should_send: status === 'ready', dispatch_token: status === 'ready' ? raw.dispatch.token : null, filename: raw.xlsx.filename, subject, html, new_total: raw.new_opportunities.total, pending_total: raw.pending.total, range_from: raw.range.from, range_to: raw.range.to } }];
